// Basic in-memory rate limiter (only for development)
const rateLimiter = {
  requests: {},
  check: function(ip, limit, windowMs) {
    const now = Date.now();
    const userRequests = this.requests[ip] || [];
    const validRequests = userRequests.filter(time => now - time < windowMs);

    if (validRequests.length >= limit) {
      return false;
    }

    validRequests.push(now);
    this.requests[ip] = validRequests;
    return true;
  }
};

const limiterMiddleware = (req, res, next) => {
  const clientIP = req.ip || req.connection.remoteAddress;
  if (!rateLimiter.check(clientIP, 100, 15 * 60 * 1000)) {
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.'
    });
  }
  next();
};

