// Secure Express Application with Best Practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');

// Initialize app
const app = express();
const PORT = process.env.PORT || 3000;

// Security middleware configuration
app.use(helmet());

// Rate limiting - prevents brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/api', limiter);

// CORS configuration - restrict origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*', // Restrict to trusted origins
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Body parsers with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL injection and XSS attacks
app.use(mongoSanitize()); // Sanitize MongoDB queries
app.use(xss()); // Sanitize user input

// Request logging
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// Request validation middleware
const validateUserId = (req, res, next) => {
  const userId = req.params.id;

  // Validate userId format (alphanumeric, 1-36 chars)
  if (!userId || /^[a-zA-Z0-9-]{1,36}$/.test(userId)) {
    next();
  } else {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid user ID format'
    });
  }
};

const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateName = (name) => {
  const nameRegex = /^[a-zA-Z\s]{1,100}$/;
  return nameRegex.test(name);
};

// Custom 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.originalUrl} not found`
  });
};

// Global error handler with safe error messages
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  // Log full error in development
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  // Handle specific errors
  if (err.name === 'CastError') {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid ID format'
    });
  }

  if (err.name === 'ValidationError') {
    return res.status(400).json({
      status: 'error',
      message: 'Validation error',
      details: Object.values(err.errors).map(e => e.message)
    });
  }

  // Handle JSON parsing errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid JSON in request body'
    });
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV !== 'production'
    ? err.message
    : 'Internal server error';

  res.status(statusCode).json({
    status: 'error',
    message
  });
};

// Middleware to handle async errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// GET /health - Health check endpoint (no validation needed)
app.get('/health', (req, res) => {
  res.set('Cache-Control', 'no-cache, no-store, must-revalidate');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// GET /users - Public list endpoint with rate limiting
app.get('/users', asyncHandler(async (req, res) => {
  // No parameters to validate for this public endpoint
  res.json({
    status: 'success',
    count: 2,
    users: [
      { id: '1', name: 'Alice', email: 'alice@example.com' },
      { id: '2', name: 'Bob', email: 'bob@example.com' },
    ]
  });
}));

// GET /users/:id - Protected user detail endpoint with validation
app.get('/users/:id', validateUserId, asyncHandler(async (req, res) => {
  const userId = req.params.id;

  // Example of input validation: ensure userId exists
  if (!userId) {
    return res.status(400).json({
      status: 'error',
      message: 'User ID is required'
    });
  }

  // securely query database (Input sanitization applied via mongoSanitize)
  const user = {
    id: userId,
    name: 'User',
    email: 'safe@example.com'
  };

  if (!user) {
    return res.status(404).json({
      status: 'error',
      message: 'User not found'
    });
  }

  res.json({
    status: 'success',
    data: user
  });
}));

// POST /users - Example of POST endpoint with validation
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body;

  // Validate required fields
  if (!name || !email) {
    return res.status(400).json({
      status: 'error',
      message: 'Name and email are required'
    });
  }

  // Validate email format
  if (!validateEmail(email)) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid email format'
    });
  }

  // Validate name format
  if (!validateName(name)) {
    return res.status(400).json({
      status: 'error',
      message: 'Name must contain only letters and spaces, max 100 characters'
    });
  }

  // Continue with user creation...
  res.status(201).json({
    status: 'success',
    message: 'User created successfully'
  });
}));

// 404 handler
app.use(notFoundHandler);

// Global error handler
app.use(errorHandler);

// Graceful shutdown handler
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  // Close server
  server.close(() => {
    console.log('HTTP server closed');
    // Close additional connections (db, etc.)
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

// Listen on specific port
const server = app.listen(PORT, () => {
  console.log(`
  ================================================================
  Server running on port ${PORT}
  Environment: ${process.env.NODE_ENV || 'development'}
  ================================================================
  `);
});

// Handle process termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

