// Secure Express application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const xss = require('xss-clean');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// Helmet helps secure Express apps by setting various HTTP headers
app.use(helmet());

// Body parser limits (prevents DoS from large payloads)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting (prevents brute force and DDoS)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', apiLimiter);

// Data sanitization against XSS
app.use(xss-clean());

// ========== HELPER FUNCTIONS ==========

/**
 * Validate request against express-validator errors
 */
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.path || 'unknown',
        message: err.msg
      }))
    });
  }
  next();
};

// ========== ROUTES ==========

// Health check - public, no rate limiting
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// API route with validation and rate limiting
app.get('/api/users', apiLimiter, (req, res) => {
  // Simulated user data - in production, fetch from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    success: true,
    data: users
  });
});

// Example POST endpoint with full input validation
app.post('/api/users', apiLimiter, [
  // Input validation rules
  body('name')
    .trim()
    .isLength({ min: 2, max: 50 })
    .escape() // Escape HTML to prevent XSS
    .withMessage('Name must be between 2 and 50 characters'),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail() // Convert to lowercase, strip angle brackets
    .withMessage('Please provide a valid email address')
], validate, (req, res) => {
  try {
    const { name, email } = req.body;

    // In production, validate against database before inserting
    // Example: check if email already exists

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: {
        name,
        email
      }
    });
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error details in development
  if (process.env.NODE_ENV === 'development') {
    console.error('Error:', err);
  }

  // Default error response
  res.status(err.status || 500).json({
    success: false,
    message: err.message || 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Route not found',
    path: req.path
  });
});

// ========== SECURITY CONFIGURATION ==========

// Set secure HTTP-only cookies flag when in production
if (process.env.NODE_ENV === 'production') {
  app.set('trust proxy', 1); // Trust first proxy (load balancer)
}

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`🔒 Server running securely on port ${PORT}`);
  console.log(`🔐 Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

