// Secure Express application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet'); // Security headers middleware
const rateLimit = require('express-rate-limit'); // Rate limiting
const xss = require('xss-clean'); // Input sanitization against XSS
const mongoSanitize = require('express-mongo-sanitize'); // MongoDB injection prevention
const cors = require('cors');
const morgan = require('morgan'); // Request logging for debugging

const app = express();

// 1. Security Headers with Helmet
app.use(helmet({
  contentSecurityPolicy: false, // Adjust based on CDN use
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate Limiting - Protect against brute force and abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting globally to all routes
app.use('/api/', limiter);

// 3. Trust proxy (if behind a proxy/load balancer)
app.set('trust proxy', 1);

// 4. Input Sanitization
app.use(xss()); // Sanitize against XSS attacks
app.use(mongoSanitize()); // Prevent MongoDB NoSQL injection

// 5. CORS Configuration
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // Restrict to specific origins in production
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 6. Body Parsing with Size Limits (prevents DoS)
app.use(express.json({
  limit: '10kb', // Limit JSON body payload
  verify: (req, res, buf) => {
    // Optional: log payload size for debugging
    req.bodySize = buf.length;
  }
}));

app.use(express.urlencoded({
  limit: '10kb',
  extended: false
}));

// 7. Request Logging
if (process.env.NODE_ENV === 'development') {
  app.use(morgan('dev'));
} else {
  app.use(morgan('combined'));
}

// 8. Custom Error Handlers
// 404 Not Found Handler
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Global Error Handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Send appropriate error response
  res.status(err.status || 500).json({
    success: false,
    error: err.message || 'Internal Server Error',
    // In production, don't expose stack traces
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Health Check (no rate limiting)
app.get('/health', async (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(503).json({
      status: 'unhealthy',
      error: 'Health check failed',
      message: error.message
    });
  }
});

// Users Endpoint with Input Validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if provided
    const { limit = 10, page = 1 } = req.query;

    // Validate limit is a positive integer
    if (limit && (isNaN(limit) || parseInt(limit) <= 0 || parseInt(limit) > 100)) {
      return res.status(400).json({
        success: false,
        error: 'Invalid limit',
        message: 'Limit must be a number between 1 and 100'
      });
    }

    // Validate page is a positive integer
    if (page && (isNaN(page) || parseInt(page) <= 0)) {
      return res.status(400).json({
        success: false,
        error: 'Invalid page',
        message: 'Page must be a positive number'
      });
    }

    // Mock user data with parameter-based filtering
    const limitValue = Math.min(Math.max(parseInt(limit) || 10, 1), 100);
    const offset = (parseInt(page) || 1 - 1) * limitValue;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    res.json({
      success: true,
      data: users.slice(offset, offset + limitValue),
      pagination: {
        page: parseInt(page) || 1,
        limit: limitValue,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      success: false,
      error: 'Internal Server Error',
      message: error.message
    });
  }
});

// 9. Graceful Server Shutdown
const server = app.listen(3000, () => {
  console.log('Secure server running on port 3000');
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
const shutdown = async (signal) => {
  console.log(`\n${signal} received. Shutting down gracefully...`);

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

