 * Environment Configuration Validator
 *
 * Validates required environment variables and provides type conversion.
 * This runs before other application code to ensure secure startup.
 */

// Required environment variables for different environments
const REQUIRED_ENV_VARS = {
  development: ['NODE_ENV'],
  production: ['NODE_ENV', 'DATABASE_URL', 'CORS_ORIGIN'],
  test: ['NODE_ENV', 'DATABASE_URL']
};

// Optional environment variables with defaults
const OPTIONAL_ENV_VARS = {
  // Server
  PORT: {
    type: 'string',
    default: '3000',
    validator: (val) => /^[0-9]+$/.test(val),
    errorMessage: 'PORT must be a number'
  },

  // Logging
  LOG_LEVEL: {
    type: 'string',
    default: 'info',
    validator: (val) => ['debug', 'info', 'warn', 'error'].includes(val.toLowerCase()),
    errorMessage: `LOG_LEVEL must be one of: debug, info, warn, error`
  },

  // Rate Limiting
  RATE_LIMIT_WINDOW_MS: {
    type: 'integer',
    default: 900000, // 15 minutes
    validator: (val) => typeof val === 'number' && val > 0,
    errorMessage: 'RATE_LIMIT_WINDOW_MS must be a positive number'
  },

  RATE_LIMIT_MAX_REQUESTS: {
    type: 'integer',
    default: 100,
    validator: (val) => typeof val === 'number' && val > 0 && val <= 10000,
    errorMessage: 'RATE_LIMIT_MAX_REQUESTS must be a number between 1 and 10000'
  },

  // Request Size Limits (bytes)
  MAX_JSON_SIZE: {
    type: 'integer',
    default: 10240, // 10KB
    validator: (val) => typeof val === 'number' && val > 0 && val <= 10485760, // 10MB max
    errorMessage: 'MAX_JSON_SIZE must be a number between 1 and 10485760'
  },

  // CORS
  CORS_ORIGIN: {
    type: 'string',
    default: '*',
    validator: (val) => {
      if (val === '*') return true;
      try {
        // If using specific origins, they should be valid URLs
        const origins = typeof val === 'string' ? val.split(',') : [];
        return origins.every(origin => origin.trim() === '*' || origin.trim().startsWith('http'));
      } catch (e) {
        return false;
      }
    },
    errorMessage: 'CORS_ORIGIN must be "*" or one or more URLs (comma-separated)'
  },

  // MongoDB URL Format Check
  DATABASE_URL: {
    type: 'string',
    validator: (val) => /^mongodb(?:(?:\+srv|:\/\/)(?:[a-z0-9]+(?:[.-][a-z0-9]+)*|(\*[a-z0-9-]+\*))(?::[a-z0-9]{1,5})?@)?([a-z0-9]+(?:[.-][a-z0-9]+)*\.[a-z]{2,})(?::\d+)?(?:\/[a-z0-9$_.+!*'(),;:@&%/?#-]+(?:[/?][a-z0-9$_.+!*'(),;:@&%/?#-]+)*)?(?:[?#][a-z0-9$_.+!*'(),;:@&%/?#-]+(?:[/?][a-z0-9$_.+!*'(),;:@&%/?#-]+)*)?$/i.test(val),
    errorMessage: 'DATABASE_URL must be a valid MongoDB connection string'
  },

  // Anthropic API Key (Optional for this app but good practice)
  ANTHROPIC_API_KEY: {
    type: 'string',
    default: '',
    validator: (val) => val.length < 10000, // Very basic check
    errorMessage: 'ANTHROPIC_API_KEY seems abnormally long'
  },

  // Stripe API Key (Optional for this app)
  STRIPE_SECRET_KEY: {
    type: 'string',
    default: '',
    validator: (val) => val.length > 0 || val.length > 0,
    errorMessage: 'STRIPE_SECRET_KEY is required for production'
  },

  // AWS Keys (Optional)
  AWS_ACCESS_KEY_ID: {
    type: 'string',
    default: '',
    validator: (val) => val.length > 0,
    errorMessage: 'AWS_ACCESS_KEY_ID is required if AWS keys are provided'
  },
  AWS_SECRET_ACCESS_KEY: {
    type: 'string',
    default: '',
    validator: (val) => val.length > 0,
    errorMessage: 'AWS_SECRET_ACCESS_KEY is required if AWS keys are provided'
  },

  // AWS Specific
  AWS_REGION: {
    type: 'string',
    default: 'us-east-1',
    validator: (val) => /^[a-z]{2}-[a-z-]+$/.test(val),
    errorMessage: 'AWS_REGION must be in format: region-code-subregion'
  }
};

/**
 * Get environment variable with validation
 */
function getEnvVar(name, required = true, defaultValue = undefined) {
  const envValue = process.env[name];

  if (required && envValue === undefined) {
    throw new Error(`Missing required environment variable: ${name}`);
  }

  if (envValue === undefined) {
    return defaultValue;
  }

  // Get configuration for this variable
  const config = OPTIONAL_ENV_VARS[name] || {};
  const { type, validator, errorMessage = `Invalid value for ${name}` } = config;

  // Type validation
  let validatedValue = envValue;

  if (type === 'integer') {
    const parsed = parseInt(envValue, 10);
    if (isNaN(parsed)) {
      throw new Error(`${errorMessage}`);
    }
    validatedValue = parsed;
  } else if (type === 'boolean') {
    validatedValue = envValue.toLowerCase() === 'true';
  }

  // Custom validator
  if (validator && !validator(validatedValue)) {
    throw new Error(`${errorMessage}: "${envValue}"`);
  }

  return validatedValue;
}

/**
 * Validate all required environment variables for current environment
 */
function validateEnvironment() {
  const nodeEnv = getEnvVar('NODE_ENV', true);

  // Get required variables for current environment
  const requiredVars = REQUIRED_ENV_VARS[nodeEnv] || [];
  const optionalVars = Object.keys(OPTIONAL_ENV_VARS);

  console.log(`🔍 Validating environment configuration for: ${nodeEnv}`);
  console.log('');

  // Validate required variables
  console.log('✅ Required Variables:');
  requiredVars.forEach(varName => {
    try {
      const value = getEnvVar(varName, true);
      // Don't log actual values for security
      if (value && (value.includes('password') || value.includes('secret') || value.includes('key'))) {
        console.log(`   ${varName}: *** HIDDEN ***`);
      } else {
        console.log(`   ${varName}=${value}`);
      }
    } catch (error) {
      console.error(`   ❌ ${varName}: Missing or invalid`);
      console.error(`      ${error.message}`);
    }
  });
  console.log('');

  // Validate environment-specific optional variables
  console.log('ℹ️  Environment-Specific Optional Variables:');
  const envVarNames = optionalVars.filter(name =>
    // Skip if already required in this environment
    !requiredVars.includes(name) &&
    // Include based on environment needs
    isVarNeededForEnvironment(name, nodeEnv)
  );

  envVarNames.forEach(varName => {
    try {
      const value = getEnvVar(varName, false);
      const config = OPTIONAL_ENV_VARS[varName];

      if (value === undefined || value === config.default) {
        // Don't log default/empty values
        console.log(`   ${varName}: *** NOT SET (using default) ***`);
      } else {
        if (value && (value.includes('password') || value.includes('secret') || value.includes('key'))) {
          console.log(`   ${varName}: *** HIDDEN ***`);
        } else {
          console.log(`   ${varName}=${value}`);
        }
      }
    } catch (error) {
      console.error(`   ⚠️  ${varName}: ${error.message}`);
    }
  });
  console.log('');

  // Summary
  console.log('✅ Configuration validated successfully!');
  return true;
}

/**
 * Determine if a variable is needed for the current environment
 */
function isVarNeededForEnvironment(varName, nodeEnv) {
  switch (varName) {
    case 'AWS_ACCESS_KEY_ID':
    case 'AWS_SECRET_ACCESS_KEY':
    case 'AWS_REGION':
      return nodeEnv === 'production' || nodeEnv === 'staging';

    case 'STRIPE_SECRET_KEY':
      return nodeEnv === 'production' || nodeEnv === 'staging';

    case 'ANTHROPIC_API_KEY':
      return nodeEnv === 'production' || nodeEnv === 'staging';

    default:
      return true;
  }
}

/**
 * Get all configuration object for app.js
 */
function getConfig() {
  return {
    // Server
    PORT: getEnvVar('PORT'),

    // Environments
    NODE_ENV: getEnvVar('NODE_ENV'),
    PRIVILEGED_MODE: process.env.NODE_ENV === 'production',

    // Logging
    LOG_LEVEL: getEnvVar('LOG_LEVEL'),
    DEBUG: process.env.DEBUG === 'true',

    // Rate Limiting
    RATE_LIMIT_WINDOW_MS: getEnvVar('RATE_LIMIT_WINDOW_MS'),
    RATE_LIMIT_MAX_REQUESTS: getEnvVar('RATE_LIMIT_MAX_REQUESTS'),

    // Request Size Limits
    MAX_JSON_SIZE: getEnvVar('MAX_JSON_SIZE', false),
    MAX_URL_ENCODED_SIZE: getEnvVar('MAX_JSON_SIZE', false), // Same limit

    // CORS
    CORS_ORIGIN: getEnvVar('CORS_ORIGIN'),
    CORS_PERMISSIVE: process.env.NODE_ENV === 'development' || process.env.NODE_ENV === 'test',

    // Database
    DATABASE_URL: getEnvVar('DATABASE_URL', true),

    // API Keys
    ANTHROPIC_API_KEY: getEnvVar('ANTHROPIC_API_KEY', false),
    STRIPE_SECRET_KEY: getEnvVar('STRIPE_SECRET_KEY', false),
    LOGFIRE_TOKEN: getEnvVar('LOGFIRE_TOKEN', false),

    // AWS
    AWS_ACCESS_KEY_ID: getEnvVar('AWS_ACCESS_KEY_ID', false),
    AWS_SECRET_ACCESS_KEY: getEnvVar('AWS_SECRET_ACCESS_KEY', false),
    AWS_REGION: getEnvVar('AWS_REGION')
  };
}

/**
 * Produce a summary of configuration for documentation
 */
function getConfigSummary() {
  const config = getConfig();

  return {
    environment: config.NODE_ENV,
    privileged: config.PRIVILEGED_MODE,
    port: config.PORT,
    logging: config.LOG_LEVEL,
    debug: config.DEBUG,

    rateLimiting: {
      enabled: true,
      window: `${Math.round(config.RATE_LIMIT_WINDOW_MS / 60000)} minutes`,
      max: config.RATE_LIMIT_MAX_REQUESTS
    },

    cors: {
      enabled: true,
      origin: config.CORS_ORIGIN,
      permissive: config.CORS_PERMISSIVE
    },

    sanitization: {
      xss: true,
      mongoSanitize: true,
      bodySize: config.MAX_JSON_SIZE ? `${config.MAX_JSON_SIZE} bytes` : '10KB (default)'
    },

    database: {
      connected: false,
      url: config.DATABASE_URL ? `${config.DATABASE_URL.split('@')[1]}` : 'Not configured'
    },

    security: {
      headers: config.PRIVILEGED_MODE,
      rateLimit: config.RATE_LIMIT_MAX_REQUESTS ? true : false,
      xss: true,
      injectionPrevention: true,
      sizeLimiting: true
    }
  };
}

// Export for use in other files
module.exports = {
  getEnvVar,
  validateEnvironment,
  getConfig,
  getConfigSummary,
  REQUIRED_ENV_VARS,
  OPTIONAL_ENV_VARS
};

