    next();
  };
}
```

#### 2. **Robust Error Handling Middleware**

```javascript
// Global error handling
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method
  });

