/**
 * Secure Express Application
 * Enhanced with comprehensive error handling and input validation
 */

const express = require('express');
const app = express();

// Security middleware
// Limit the amount of data clients can send
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting middleware (using express-rate-limit)
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.',
  handler: (req, res) => {
    res.status(429).json({ error: 'Rate limit exceeded' });
  }
});
app.use('/', limiter);

// Cookie parser with secure settings
app.use(require('cookie-parser')({
  secret: process.env.COOKIE_SECRET || 'default-secret-key',
  cookie: {
    httpOnly: true,  // Prevents JavaScript access to cookies
    secure: process.env.NODE_ENV === 'production', // HTTPS only in production
    sameSite: 'strict', // CSRF protection
    maxAge: 3600000 // 1 hour
  }
}));

// Validate JSON content type
app.use((req, res, next) => {
  if (req.is('json') && Buffer.byteLength(JSON.stringify(req.body)) > 10000) {
    return res.status(400).json({ error: 'Request body too large' });
  }
  next();
});

/**
 * Health check endpoint
 * Should be open but minimal, to reduce attack surface
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * User endpoint with comprehensive validation
 */
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const allowedParams = ['limit', 'offset', 'search'];
    const invalidParams = Object.keys(req.query).filter(
      param => !allowedParams.includes(param)
    );

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        invalidParams: invalidParams,
        allowedParams: allowedParams
      });
    }

    // Validate numeric limits
    if (req.query.limit && (isNaN(req.query.limit) || parseInt(req.query.limit) < 1)) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be a positive integer'
      });
    }

    if (req.query.offset && (isNaN(req.query.offset) || parseInt(req.query.offset) < 0)) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        message: 'Offset must be a non-negative integer'
      });
    }

    // Validation passed - return response
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply limit if provided
    const limit = req.query.limit ? parseInt(req.query.limit) : undefined;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;

    const paginatedUsers = users
      .slice(offset, limit ? offset + limit : users.length)
      .map(user => ({
        id: user.id,
        name: user.name,
        email: sanitizeEmail(user.email) // Sanitize sensitive data
      }));

    res.json({
      success: true,
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit: limit || users.length,
        offset: offset
      }
    });

  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : 'An error occurred'
    });
  }
});

/**
 * Express error handling middleware
 * Must be registered after all routes
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Determine response based on error type
  let statusCode = 500;
  let errorData = {
    error: 'Internal server error'
  };

  // Handle known error types
  if (err.status) {
    statusCode = err.status;
    errorData = err;
  } else if (err instanceof SyntaxError) {
    statusCode = 400;
    errorData = {
      error: 'Bad request',
      message: 'Invalid JSON format in request body'
    };
  } else if (err instanceof ValidationError) {
    statusCode = 400;
    errorData = err;
  }

  // In development, include additional error details
  if (process.env.NODE_ENV === 'development') {
    errorData.stack = err.stack;
  }

  res.status(statusCode).json(errorData);
});

// Custom validation error class
class ValidationError extends Error {
  constructor(message, field = null) {
    super(message);
    this.name = 'ValidationError';
    this.status = 400;
    if (field) {
      this.field = field;
    }
  }
}

/**
 * Sanitization utility functions
 */

/**
 * Basic email sanitization
 * Removes potentially dangerous characters and normalizes
 */
function sanitizeEmail(email) {
  try {
    if (!email) return '';
    // Convert to lowercase and trim
    return email.toLowerCase().trim().replace(/\s+/g, '');
  } catch (error) {
    console.error('Email sanitization error:', error);
    return '';
  }
}

/**
 * Sanitize output data
 */
function sanitizeOutput(data) {
  if (typeof data !== 'object' || data === null) {
    return data;
  }

  // Deep clone to avoid mutating original
  const cloned = JSON.parse(JSON.stringify(data));

  // Remove sensitive data fields
  const sensitiveFields = ['password', 'token', 'secret', 'apiKey'];
  const sanitizeRecursive = (obj) => {
    for (const key in obj) {
      if (sensitiveFields.some(field => key.toLowerCase().includes(field))) {
        // Replace with placeholder
        obj[key] = 'REDACTED';
      }
      if (typeof obj[key] === 'object' && obj[key] !== null) {
        sanitizeRecursive(obj[key]);
      }
    }
  };

  sanitizeRecursive(cloned);
  return cloned;
}

// Ensure sanitizeOutput is applied to responses
const originalJson = res.json;
app.use((req, res, next) => {
  const originalSend = res.json.bind(res);
  res.json = function(data) {
    // Sanitize sensitive data before sending
    const sanitizedData = sanitizeOutput(data);
    return originalSend(sanitizedData);
  };
  next();
});

// Graceful shutdown handler
const gracefulShutdown = (signal) => {
  console.log(`\nReceived ${signal}, shutting down gracefully...`);
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force exit after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Start server with proper validation
const PORT = process.env.PORT || 3000;

// Validate port number
if (!PORT || isNaN(PORT) || PORT < 1 || PORT > 65535) {
  console.error('Invalid port number');
  process.exit(1);
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  console.error('Shutting down...')
  // Don't call exit() immediately, let gracefulShutdown handle it
  setTimeout(() => process.exit(1), 1000);
});

// Handle unhandled promise rejections
