// Security middleware
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded payload size
app.use(express.text({ limit: '10kb' })); // Limit text payload size

// Rate limiting middleware (to prevent brute force attacks)
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes window
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 300
  }
});
app.use('/health', limiter); // Apply to health endpoint specifically

// Helmet middleware for security headers (if available)
try {
  const helmet = require('helmet');
  app.use(helmet());
} catch (err) {
  console.warn('Helmet middleware not installed. Consider installing it for enhanced security.');
}

// Request validation middleware
function validateRequest(req, res, next) {
  // Validate content-type header for JSON requests
  if (req.is('application/json') && !req.is('json')) {
    return res.status(415).json({ error: 'Unsupported Media Type. Expected application/json.' });
  }

  next();
}

// Health check endpoint with additional security
app.get('/health', (req, res) => {
  try {
    // Validate IP-based rate limiting already applied
    res.set('X-Content-Type-Options', 'nosniff');
    res.set('X-Frame-Options', 'DENY');
    res.set('X-XSS-Protection', '1; mode=block');
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      version: process.env.npm_package_version || 'unknown'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation and sanitized output
app.get('/users', (req, res) => {
  try {
    res.set('X-Content-Type-Options', 'nosniff');
    res.set('X-Frame-Options', 'DENY');
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ]);
  } catch (error) {
