// Secure version with comprehensive error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const app = express();

// ============================================
// Security Headers (via Helmet)
// ============================================
app.use(helmet());

// ============================================
// Security Configuration
// ============================================
const isDevelopment = process.env.NODE_ENV !== 'production';

// Rate limiting: Limit each IP to 100 requests per 15 minutes
// Adjust based on your application needs
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  // Skip rate limiting in development for easier testing
  skip: isDevelopment ? (req) => true : undefined
});

// Strict rate limiting for POST/PUT/DELETE requests
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: {
    error: 'Too many write attempts from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  skip: isDevelopment ? (req) => true : undefined
});

// ============================================
// Body Parsing with Security
// ============================================
// These limit request body sizes to prevent resource exhaustion attacks
app.use(express.json({ limit: '10kb' })); // 10kb maximum body
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// Request Validation Middleware
// ============================================
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || 'unknown',
        message: err.msg,
        value: sanitizeInput(req.body?.[err.path] || req.query?.[err.path] || err.value)
      }))
    });
  }
  next();
};

// Helper function to sanitize user input
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;

  // Remove potentially dangerous characters
  return input
    .trim()
    .replace(/[<>]/g, '')
    .replace(/javascript:/gi, '')
    .replace(/on\w+=/gi, '')
    .replace(/data:/gi, '')
    .replace(/vbscript:/gi, '');
};

// ============================================
// Route Handlers
// ============================================

// Health check endpoint (protected by rate limiter)
app.get('/health', apiLimiter, (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    // Only include detailed info in development
    if (isDevelopment) {
      healthData.memory = process.memoryUsage().heapUsed;
      healthData.environment = process.env.NODE_ENV;
    }

    // Use strict boolean type coercion for boolean fields
    res.json(healthData);
  } catch (error) {
    handleError(error, 'Health check endpoint', req, res);
  }
});

// Users endpoint with input validation and rate limiting
app.get('/users', apiLimiter, (req, res) => {
  try {
    // Safely sanitize query parameters
    const safeQueryParams = {
      page: sanitizeInput(req.query.page),
      limit: sanitizeInput(req.query.limit)
    };

    // Fail gracefully for invalid inputs
    const page = parseInt(safeQueryParams.page) || 1;
    const limit = parseInt(safeQueryParams.limit) || 10;

    // Prevent excessive pagination to avoid resource exhaustion
    const safeLimit = Math.min(Math.max(limit, 1), 100);

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    handleError(error, 'Users endpoint', req, res);
  }
});

// Create user endpoint with full validation
app.post('/users', strictLimiter, [
  // Validate email format
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Please provide a valid email address'),
  // Validate name (min 2 chars, max 50 chars, only letters)
  body('name')
    .trim()
    .isLength({ min: 2, max: 50 })
    .matches(/^[a-zA-Z\s]+$/)
    .withMessage('Name must be 2-50 characters (letters only)'),
  // Validate optional phone number (optional but format-tested if provided)
  body('phone')
    .optional()
    .matches(/^[\d\s\-\+\(\)]+$/)
    .withMessage('Please provide a valid phone number')
    .isLength({ max: 20 })
    .withMessage('Phone number too long')
], validateRequest, (req, res) => {
  try {
    // Sanitize all inputs before processing
    const sanitizedData = {
      name: sanitizeInput(req.body.name),
      email: sanitizeInput(req.body.email),
      phone: sanitizeInput(req.body.phone)
    };

    // Additional business logic would go here
    // For demonstration, we'll just return a success response

    res.status(201).json({
      id: Date.now(),
      ...sanitizedData,
      createdAt: new Date().toISOString()
    });
  } catch (error) {
    handleError(error, 'Create user endpoint', req, res);
  }
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  // Log errors in development
  if (isDevelopment) {
    console.error('Error:', {
      message: err.message,
      stack: err.stack,
      url: req.url,
      method: req.method,
      ip: req.ip,
      userAgent: req.get('user-agent')
    });
  }

  // Return appropriate error response
  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { message: err.message }),
    timestamp: new Date().toISOString()
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path
  });
});

// ============================================
// Helper Functions
// ============================================

// Centralized error handling function
const handleError = (error, context, req, res) => {
  // Log in development
  if (isDevelopment) {
    console.error(`[${context}] Error:`, error.message);
  }

  // Get appropriate status code
  const statusCode = error.statusCode || 500;

  // Return sanitized error message
  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal server error' : error.message,
    ...(isDevelopment && { details: error.message })
  });
};

// ============================================
// Start Server
// ============================================
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`Secure server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${isDevelopment ? 'development' : 'production'}`);
});

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  process.exit(0);
});

module.exports = app;

