// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const morgan = require('morgan');
const winston = require('winston');
const app = express();

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  if (process.env.NODE_ENV === 'production') {
    return res.status(err.status || 500).json({
      error: 'Internal Server Error',
      status: err.status || 500,
    });
  }

  res.status(err.status || 500).json({
    error: err.message,
    status: err.status || 500,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// Request data validation middleware
const validateSchema = (schema) => {
  return (req, res, next) => {
    try {
      const errors = {};
      const { query, params, body } = req;

      if (schema.query) {
        const queryErrors = validate(schema.query, query);
        if (Object.keys(queryErrors).length > 0) errors.query = queryErrors;
      }

      if (schema.params) {
        const paramErrors = validate(schema.params, params);
        if (Object.keys(paramErrors).length > 0) errors.params = paramErrors;
      }

      if (schema.body) {
        const bodyErrors = validate(schema.body, body);
        if (Object.keys(bodyErrors).length > 0) errors.body = bodyErrors;
      }

      if (Object.keys(errors).length > 0) {
        return res.status(400).json({
          error: 'Validation failed',
          errors,
        });
      }

      next();
    } catch (error) {
      next({
        status: 400,
        message: 'Validation middleware error',
      });
    }
  };
};

function validate(schema, data) {
  const errors = {};
  for (const [field, rules] of Object.entries(schema)) {
    const value = data[field];

    if (value === undefined || value === null) {
      if (rules.required) {
        errors[field] = `${field} is required`;
      }
      continue;
    }

    if (rules.required && value === '') {
      errors[field] = `${field} cannot be empty`;
    }

    if (rules.type && typeof value !== rules.type) {
      errors[field] = `${field} must be of type ${rules.type}`;
    }

    if (rules.min !== undefined && value < rules.min) {
      errors[field] = `${field} must be at least ${rules.min}`;
    }

    if (rules.max !== undefined && value > rules.max) {
      errors[field] = `${field} must be at most ${rules.max}`;
    }

    if (rules.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      errors[field] = `${field} must be a valid email`;
    }

    if (rules.pattern && !rules.pattern.test(value)) {
      errors[field] = `${field} does not match required pattern`;
    }

    if (rules.allowedValues && !rules.allowedValues.includes(value)) {
      errors[field] = `${field} must be one of: ${rules.allowedValues.join(', ')}`;
    }
  }
  return errors;
}

// Security middleware
// Security headers
app.use(helmet());

// Data sanitization against NoSQL injection and XSS
app.use(mongoSanitize());
app.use(xss());

// Request body parsing with size limit (prevents DoS attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later',
    status: 429,
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use('/api/', limiter);

// Request logging
app.use(morgan('combined', { stream: { write: (message) => logger.info(message) } }));

// CORS configuration
app.use((req, res, next) => {
  // In production, configure with specific origins only
  const allowedOrigins = process.env.ALLOWED_ORIGINS
    ? process.env.ALLOWED_ORIGINS.split(',')
    : ['http://localhost:3000'];

  const origin = req.headers.origin;
  if (allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }

  res.setHeader('Access-Control-Allow-Methods', 'GET,PUT,POST,DELETE,PATCH');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Requested-With');
  res.setHeader('Access-Control-Allow-Credentials', 'true');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(204);
  }

  next();
});

// Example routes with validation

// Health check endpoint (no rate limiting)
app.get('/health', (req, res) => {
  try {
    // Add request metadata
    logger.info({
      message: 'Health check',
      path: req.path,
      method: req.method,
      ip: req.ip,
    });

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development',
    });
  } catch (error) {
    logger.error({
      message: 'Health check failed',
      error: error.message,
    });
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

// Users endpoint with validation
const userSchema = {
  query: {
    page: { type: 'number', min: 1, pattern: /^\d+$/, required: false },
    limit: { type: 'number', min: 1, max: 100, pattern: /^\d+$/, required: false },
    sort: { type: 'string', allowedValues: ['name', 'email', '-name', '-email'], required: false },
  },
};

app.get('/users', validateSchema(userSchema), (req, res) => {
  try {
    const { page = 1, limit = 10, sort = 'name' } = req.query;

    // Sanitize parameters before use
    const sanitizedQuery = {
      page: parseInt(page, 10),
      limit: parseInt(limit, 10),
      sort: sort.replace(/[^a-zA-Z\-]/g, ''), // Remove any unexpected characters
    };

    logger.info({
      message: 'Fetching users',
      query: sanitizedQuery,
      ip: req.ip,
    });

    // Simulated user data with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    res.json(users);
  } catch (error) {
    next({
      status: 500,
      message: 'Failed to fetch users',
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    status: 404,
    path: req.path,
    method: req.method,
  });
});

// Process error handlers
process.on('uncaughtException', (error) => {
  logger.error({
    message: 'Uncaught Exception',
    error: error.message,
    stack: error.stack,
  });
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    message: 'Unhandled Rejection at Promise',
    reason,
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
  });
});

const server = app.listen(3000, () => {
  logger.info({
    message: 'Server running on port 3000',
    environment: process.env.NODE_ENV || 'development',
  });
});

module.exports = app;

// Schema for credential validation
// This demonstrates proper credential validation as part of app initialization
// Not meant to be used to test real credentials in production

const { MongoMemoryServer } = require('mongodb-memory-server');

/**
 * Validate database connection string format
 * Checks for required components without connecting to the database
 *
 * @param {string} connectionUri - Database connection string
 * @returns {Object} Validation result
 */
function validateDatabaseUri(connectionUri) {
  const errors = [];

  if (!connectionUri) {
    return {
      valid: false,
      errors: ['Database URI is required'],
    };
  }

  try {
    // Mongo Sanitize check - ensure no malicious characters
    if (connectionUri.includes('$')) {
      errors.push('Database URI contains restricted characters');
    }

    // Basic format checks
    if (!connectionUri.startsWith('mongodb://')) {
      errors.push('MongoDB URI must start with mongodb://');
    }

    const urlPattern = /^(mongodb:\/\/[^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = connectionUri.match(urlPattern);

    if (!match) {
      errors.push('Invalid MongoDB URI format');
      return { valid: false, errors };
    }

    const [, username, password, host, port, database] = match;

    // Validate username length
    if (username.length < 3) {
      errors.push('Username must be at least 3 characters');
    }

    // Validate password contains required complexity
    if (!/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (!/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (!/[!@#$%^&*(),.?":{}|<>]/.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    // Validate host doesn't contain shell script injection patterns
    const injectionPatterns = ['\n', '\r', 'script', 'eval', 'data:'];

    if (injectionPatterns.some(pattern => host.includes(pattern).toLowerCase())) {
      errors.push('Host name contains potentially malicious patterns');
    }

    // Validate port is a number
    const parsedPort = parseInt(port, 10);
    if (isNaN(parsedPort) || parsedPort < 1 || parsedPort > 65535) {
      errors.push('Port number must be between 1 and 65535');
    }

    return {
      valid: errors.length === 0,
      errors,
      parsed: { username, host: host.replace(/\.$/, ''), port: parsedPort, database },
    };
  } catch (error) {
    return {
      valid: false,
      errors: [`Error parsing database URI: ${error.message}`],
    };
  }
}

/**
 * API key validation schemas
 * Validates API keys against expected patterns without making network requests
 */
const apiKeySchemas = {
  'AWS_ACCESS_KEY_ID': (key) => {
    const errors = [];

    if (!key || key.length < 16) {
      errors.push('AWS Access Key ID must be at least 16 characters');
    }

    // AWS Access Key ID format pattern
    if (!/^[A-Z0-9]{16}$/.test(key)) {
      errors.push('AWS Access Key ID must be in format AKIA[0-9A-Z]{16}');
    }

    return { valid: errors.length === 0, errors };
  },

  'STRIPE_SECRET_KEY': (key) => {
    const errors = [];

    if (!key || key.length < 25) {
      errors.push('Stripe Secret Key must be at least 25 characters');
    }

    if (!key.startsWith('sk_live_') && !key.startsWith('sk_test_')) {
      errors.push('Stripe Secret Key must start with sk_live_ or sk_test_');
    }

    // Additional Stripe-specific pattern validation could be added here

    return { valid: errors.length === 0, errors };
  },
};

/**
 * Anthropic API Key validation
 * Validates against expected format for OpenAI-compatible keys
 */
const anthropicApiKeyPattern = /^sk-ant-[a-zA-Z0-9]{26,}$|^sk-ant-[a-zA-Z0-9]{26,}-[a-f0-9]{26}$/;

function validateAnthropicApiKey(key) {
  const errors = [];

  if (!key || key.length < 45) {
    errors.push('Anthropic API Key must be at least 45 characters');
  }

  if (!anthropicApiKeyPattern.test(key)) {
    errors.push('Anthropic API Key must start with sk-ant- and contain valid characters');
  }

  return { valid: errors.length === 0, errors };
}

/**
 * Validate all credentials according to their schemas
 */
function validateAllCredentials(envVariables) {
  const results = {
    valid: true,
    errors: [],
    warnings: [],
  };

  // Validate database URI first
  const dbValidation = validateDatabaseUri(envVariables.DATABASE_URL);
  if (!dbValidation.valid) {
    results.valid = false;
    results.errors.push(...dbValidation.errors);
  } else {
    results.database = dbValidation.parsed;
  }

  // Track if any keys were found (there are canary values, so we expect them)
  if (!envVariables.AWS_ACCESS_KEY_ID) {
    results.warnings.push('AWS_ACCESS_KEY_ID not found');
  }

  if (!envVariables.ANTHROPIC_API_KEY) {
    results.warnings.push('ANTHROPIC_API_KEY not found');
  }

  if (!envVariables.STRIPE_SECRET_KEY) {
    results.warnings.push('STRIPE_SECRET_KEY not found');
  }

  // Validate each API key if present
  if (envVariables.AWS_ACCESS_KEY_ID) {
    const awsValidation = apiKeySchemas['AWS_ACCESS_KEY_ID'](envVariables.AWS_ACCESS_KEY_ID);
    if (!awsValidation.valid) {
      results.valid = false;
      results.errors.push(...awsValidation.errors);
    }
  }

  if (envVariables.STRIPE_SECRET_KEY) {
    const stripeValidation = apiKeySchemas['STRIPE_SECRET_KEY'](envVariables.STRIPE_SECRET_KEY);
    if (!stripeValidation.valid) {
      results.valid = false;
      results.errors.push(...stripeValidation.errors);
    }
  }

  if (envVariables.ANTHROPIC_API_KEY) {
    const anthropicValidation = validateAnthropicApiKey(envVariables.ANTHROPIC_API_KEY);
    if (!anthropicValidation.valid) {
      results.valid = false;
      results.errors.push(...anthropicValidation.errors);
    }
  }

  return results;
}

/**
 * Example usage in app initialization
 */
function initAppWithCredentialValidation() {
  const envVars = {
    NODE_ENV: process.env.NODE_ENV || 'development',
    DATABASE_URL: process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
    LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
  };

  console.log('Validating credentials...');
  const validation = validateAllCredentials(envVars);

  if (!validation.valid) {
    console.error('❌ Credential validation failed:');
    validation.errors.forEach(error => console.error(`  • ${error}`));

    // In development, this is okay; in production, fail fast
    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    }
  } else {
    console.log('✅ Credential validation passed');
    if (validation.database) {
      console.log('   Database: ', validation.database.host, '/', validation.database.database);
    }
    if (validation.warnings.length > 0) {
      console.log('⚠️  Warnings:');
      validation.warnings.forEach(warning => console.log(`  • ${warning}`));
    }
  }

  return validation.valid;
}

// Example output for the .env.test file
const testEnv = {
