// Improved application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet');
const validator = require('validator');
const rateLimit = require('express-rate-limit');

// Validate required environment variables
const requiredEnvVars = ['PORT', 'NODE_ENV'];
const missingEnvVars = requiredEnvVars.filter(env => !process.env[env]);
if (missingEnvVars.length > 0) {
  console.error('Error: Missing required environment variables:', missingEnvVars.join(', '));
  process.exit(1);
}

const app = express();
const PORT = parseInt(process.env.PORT, 10) || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Security middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' })); // Prevent DoS via large payloads

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Request validation middleware
const validateEmail = (email) => {
  return validator.isEmail(email) && validator.blacklist(email, '<>');
};

// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Error handling middleware
const handleErrors = (err, req, res, next) => {
  console.error('Error:', {
    name: err.name,
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  if (err.isOperational) {
    return res.status(err.statusCode).json({ error: err.message });
  }

  // Development mode: return stack trace
  if (NODE_ENV === 'development') {
    return res.status(500).json({
      error: 'Internal Server Error',
      stack: err.stack,
    });
  }

  // Production: generic error message
  res.status(500).json({ error: 'Internal Server Error' });
};

// Database error handler
const handleDatabaseError = (err, req, res, next) => {
  if (err.code) {
    console.error('Database Error:', {
      code: err.code,
      message: err.message,
      query: err.sql,
    });
  }
  throw new AppError('Database operation failed', 500);
};

// 404 handler
app.use((req, res, next) => {
  next(new AppError(`Path not found: ${req.method} ${req.path}`, 404));
});

// Routes
app.get('/health', (req, res) => {
  // Validate query parameters if present
  const { service } = req.query;

  if (service && !validator.isAlpha(service.replace(/-/g, ''))) {
    return res.status(400).json({ error: 'Invalid service name parameter' });
  }

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    node: process.version,
  });
});

app.get('/users', (req, res, next) => {
  try {
    const { search, limit } = req.query;

    // Validate and sanitize search parameter
    if (search) {
      if (typeof search !== 'string') {
        return res.status(400).json({ error: 'Search parameter must be a string' });
      }
      if (validator.trim(search).length > 100) {
        return res.status(400).json({ error: 'Search parameter exceeds maximum length' });
      }
      if (!validator.isAlphanumeric(validator.trim(search))) {
        return res.status(400).json({ error: 'Search parameter contains invalid characters' });
      }
    }

    // Validate limit parameter
    if (limit) {
      const parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({ error: 'Limit must be an integer between 1 and 100' });
      }
    }

    // Mock user data - in real app, validate against schema
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filter if search provided
    const filteredUsers = search
      ? users.filter(user =>
          user.name.toLowerCase().includes(search.toLowerCase()) ||
          user.email.toLowerCase().includes(search.toLowerCase())
        )
      : users;

    // Apply limit if provided
    const limitedUsers = limit ? filteredUsers.slice(0, parseInt(limit, 10)) : filteredUsers;

    res.json(limitedUsers);
  } catch (err) {
    next(err);
  }
});

// Error handlers
app.use(handleDatabaseError);
app.use(handleErrors);

// Start server with error handling
app.listen(PORT, (err) => {
  if (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

module.exports = app;

