const express = require('express');
const app = express();

// Import security middleware
const helmet = require('helmet');

// Apply security headers
app.use(helmet({
  contentSecurityPolicy: false, // Disable CSP for development
  crossOriginEmbedderPolicy: false,
  crossOriginOpenerPolicy: false,
  crossOriginResourcePolicy: false,
}));

// Validate Content-Type for non-GET requests
const allowedContentTypes = ['application/json', 'application/x-www-form-urlencoded'];

app.use((req, res, next) => {
  // Allow bypass for health endpoint and GET requests
  if (req.path === '/health' || req.method === 'GET') {
    return next();
  }

  // Validate Content-Type header
  const contentType = req.get('Content-Type');
  if (!contentType || !allowedContentTypes.includes(contentType)) {
    return res.status(415).json({
      error: 'Unsupported Content-Type',
      details: 'Only application/json and application/x-www-form-urlencoded are allowed'
    });
  }
  next();
});

// Limit body size to prevent resource exhaustion
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Get port from environment or default to 3000
const PORT = process.env.PORT || 3000;

// Validate critical environment variables
function validateEnvironment() {
  const errors = [];
  const requiredEnvVars = ['NODE_ENV'];

  for (const envVar of requiredEnvVars) {
    if (!process.env[envVar]) {
      errors.push(`Missing required environment variable: ${envVar}`);
    }
  }

  return errors;
}

// Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Add unhandled exception handling
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Don't exit in development to allow debugging
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Add unhandled promise rejection handling
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Don't exit in development to allow debugging
  if (process.env.NODE_ENV === 'production') {
    throw reason;
  }
});

// Health endpoint - minimal response for monitoring
app.get('/health', (req, res) => {
  res.json({
    status: 'healthy',
    timestamp: new Date().toISOString()
  });
});

// Add global error handler middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Determine status code
  const statusCode = err.status || err.statusCode || 500;

  // In production, don't expose detailed error messages
  // Only include error code and message
  const response = {
    error: err.message || 'Internal Server Error',
    code: statusCode
  };

  // Include stack trace only in non-production environments
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

module.exports = app;

