const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');

// Security middleware
app.use(helmet()); // Security headers middleware
app.use(xss()); // XSS protection middleware

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all API routes
app.use('/api', apiLimiter);

// Health check (no rate limiting needed)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users route with error handling
app.get('/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate response for malicious input
    const sanitizedUsers = users.map(user => ({
      id: Number.isInteger(user.id) ? user.id : 0,
      name: typeof user.name === 'string' ? user.name.trim() : 'Unknown',
      email: typeof user.email === 'string'
        ? user.email.toLowerCase().trim().match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)
          ? user.email
          : 'invalid-email@example.com'
        : 'invalid-email@example.com'
    }));

    res.json({
      success: true,
      data: sanitizedUsers,
      count: sanitizedUsers.length,
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      success: false,
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose sensitive information in production
  if (process.env.NODE_ENV === 'production') {
    res.status(err.status || 500).json({
      success: false,
      error: process.env.NODE_ENV === 'production'
        ? 'Internal server error'
        : err.message
    });
  } else {
    res.status(err.status || 500).json({
      success: false,
      error: err.message,
      stack: err.stack
    });
  }
});

// Graceful shutdown
const server = app.listen(3000, () => {
  console.log(`Server running on port 3000 in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle process termination signals
const terminate = () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
};

process.on('SIGTERM', terminate);
process.on('SIGINT', terminate);

module.exports = app;

