// Secure Express Application with Error Handling and Input Validation
// Review focused: Error handling and input validation best practices

const express = require('express');
const app = express();

// ============================================
// Security Middleware Configuration
// ============================================

// Parse JSON bodies (with size limit to prevent DoS attacks)
app.use(express.json({
  limit: '10kb', // Prevent large payload DoS
  strict: true
}));

// Parse URL-encoded bodies
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// ============================================
// Security Header Middleware
// ============================================

app.use((req, res, next) => {
  // Content Security Policy - Prevent XSS
  // Restricts source URLs for scripts, styles, images
  res.setHeader('Content-Security-Policy',
    "default-src 'self'; " +
    "script-src 'self' 'unsafe-eval' 'unsafe-inline'; " +
    "style-src 'self' 'unsafe-inline'; " +
    "img-src 'self' data: https:; " +
    "connect-src 'self'"
  );

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Enable XSS protection (older browsers)
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Control referrer information
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  next();
});

// ============================================
// Input Validation Middleware
// ============================================

/**
 * Validates input parameters for user ID
 * Prevents SQL injection, malformed requests, and invalid data
 */
function validateUserId(req, res, next) {
  const userId = req.params.id;

  // Validate that userId exists
  if (!userId) {
    return res.status(400).json({
      error: 'Validation failed',
      code: 'VALIDATION_ERROR',
      details: [{
        field: 'id',
        msg: 'User ID is required'
      }]
    });
  }

  // Validate that userId is numeric
  const isNumeric = /^[0-9]+$/.test(userId);
  if (!isNumeric) {
    return res.status(400).json({
      error: 'Validation failed',
      code: 'VALIDATION_ERROR',
      details: [{
        field: 'id',
        msg: 'User ID must be a numeric value'
      }]
    });
  }

  // Optional: Validate range
  const userIdNum = parseInt(userId, 10);
  if (userIdNum < 1 || userIdNum > 10000) {
    return res.status(400).json({
      error: 'Validation failed',
      code: 'VALIDATION_ERROR',
      details: [{
        field: 'id',
        msg: 'User ID must be between 1 and 10000'
      }]
    });
  }

  next();
}

// ============================================
// Unified Error Handling Middleware
// ============================================

/**
 * Centralized error handling for all routes
 * Provides consistent error responses and structured logging
 */
app.use((err, req, res, next) => {
  // Log full error stack in development for debugging
  console.error('Error:', err);
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  // Determine appropriate HTTP status code
  let statusCode = err.status || 500;
  const isAuthError = err.code === 'AUTH_ERROR';

  // Get user-friendly message in production
  let message = err.message || 'Internal Server Error';

  if (process.env.NODE_ENV === 'production') {
    // Hide technical details in production
    message = isAuthError
      ? 'Authentication required'
      : 'An error occurred. Please try again later.';
  }

  // Send structured error response
  res.status(statusCode).json({
    status: 'error',
    code: err.code || 'SERVER_ERROR',
    message: message,
    timestamp: new Date().toISOString()
  });
});

